// Domain 3 — Security. Original flashcards.
let n = 0;
const c = (topic, front, back) => ({ id: `d3-f${String(++n).padStart(3, '0')}`, topic, front, back });

export default [
  c('3.1', 'PAM `required` vs `requisite`?', 'Both must succeed. `required` keeps running the stack and fails at the end; `requisite` returns failure immediately.'),
  c('3.1', 'Tools that generate shared PAM stacks?', 'RHEL: `authselect` (`system-auth`, `password-auth`). Debian/Ubuntu: `pam-auth-update` (`common-*`). Hand edits get overwritten.'),
  c('3.1', 'Where do local Polkit rules go?', '`/etc/polkit-1/rules.d/*.rules` (JavaScript). Actions are declared in `/usr/share/polkit-1/actions/*.policy`. `pkaction --verbose` shows defaults.'),
  c('3.1', 'LDAP ports?', '389 for LDAP and LDAP with StartTLS; 636 for LDAPS.'),
  c('3.1', 'Kerberos essentials?', 'KDC on port 88 issues a TGT, then service tickets. `kinit`, `klist`, `kdestroy`; `/etc/krb5.conf`; host keys in `/etc/krb5.keytab`; clock skew limit 5 minutes.'),
  c('3.1', 'Join a host to AD or IdM?', '`realm discover example.com`, `realm join -U Administrator example.com`, `realm permit -g group`. It configures SSSD, Kerberos and PAM/NSS.'),
  c('3.1', 'rsyslog `@` vs `@@`?', '`@host:514` forwards over UDP; `@@host:514` over TCP.'),
  c('3.1', 'Make the journal survive reboots?', '`Storage=persistent` in `/etc/systemd/journald.conf` (or create `/var/log/journal` with `auto`), then restart systemd-journald.'),
  c('3.1', 'Persistent audit rules?', 'Files ending `.rules` in `/etc/audit/rules.d/`, merged by `augenrules --load` into `/etc/audit/audit.rules`. `auditctl` changes are runtime only.'),
  c('3.2', 'firewalld runtime vs permanent?', 'No `--permanent`: running firewall only. `--permanent`: saved config only. `--reload` loads permanent into runtime; `--runtime-to-permanent` saves runtime.'),
  c('3.2', 'How firewalld picks a zone?', 'Source binding first, then the incoming interface\'s zone, then the default zone (`public`).'),
  c('3.2', 'firewalld service vs port?', 'A service is an XML definition that can bundle ports, protocols and helpers (`--add-service=ftp`). `--add-port=8443/tcp` opens one port.'),
  c('3.2', 'ufw rule order?', 'First match wins. Put specific denies first: `ufw insert 1 deny from 203.0.113.50`. `ufw status numbered` shows positions.'),
  c('3.2', 'What does `iptables -V` showing `(nf_tables)` mean?', 'iptables-nft: iptables syntax that writes nftables rules. `(legacy)` would mean the old x_tables back end.'),
  c('3.2', 'Where do DNAT and SNAT happen?', 'DNAT: prerouting (and output). SNAT and masquerade: postrouting (nftables also allows SNAT in input).'),
  c('3.2', 'Persist IP forwarding?', '`net.ipv4.ip_forward = 1` in `/etc/sysctl.d/90-router.conf`, then `sysctl --system`. Runtime: `sysctl -w net.ipv4.ip_forward=1`.'),
  c('3.3', 'Which `/etc/sudoers.d` files are skipped?', 'Names that contain a `.` or end in `~`. Use mode 0440 and edit with `visudo -f`.'),
  c('3.3', 'sudoers `NOPASSWD:` and `NOEXEC:`?', '`NOPASSWD:` no password prompt for those commands. `NOEXEC:` the command cannot run other programs, blocking shell escapes.'),
  c('3.3', 'Special permission bits?', 'setuid 4000 (`s` user x), setgid 2000 (`s` group x; dirs inherit group), sticky 1000 (`t`; only owners delete, as on `/tmp` 1777).'),
  c('3.3', 'Files and dirs created under umask 027?', 'Files 640 (`rw-r-----`), directories 750 (`rwxr-x---`).'),
  c('3.3', '`chattr +i` vs `+a`?', '`i` immutable: no write, delete, rename or link, even by root. `a` append only. Check with `lsattr`; only root can set or clear.'),
  c('3.3', 'ACL mask?', 'Upper limit for named users, named groups and the owning group. `chmod g=...` changes it; `getfacl` shows `#effective:`.'),
  c('3.3', '`chcon` vs `semanage fcontext`?', '`chcon` labels the file now but a relabel or `restorecon` undoes it. `semanage fcontext -a -t TYPE "path(/.*)?"` + `restorecon -Rv` is permanent.'),
  c('3.3', 'Service on a non-standard port under SELinux?', '`semanage port -a -t http_port_t -p tcp 8090` (use `-m` if the port already has a type).'),
  c('3.3', 'sshd keyword precedence?', 'First value read wins; `Include sshd_config.d/*.conf` near the top means drop-ins override later lines. Verify with `sshd -T`.'),
  c('3.3', 'Key login ignored though key is in authorized_keys?', '`StrictModes`: home, `~/.ssh` (700) or `authorized_keys` (600) writable by group/others. Log: "bad ownership or modes".'),
  c('3.3', 'Block a module completely?', '`install <mod> /bin/false` plus `blacklist <mod>` in `/etc/modprobe.d/*.conf`. blacklist alone stops only alias autoloading.'),
  c('3.3', 'Secure Boot chain?', 'Firmware db verifies shim (Microsoft UEFI CA), shim verifies GRUB (distro key or MOK), GRUB the kernel, kernel the modules. `mokutil --sb-state`.'),
  c('3.4', 'pam_tally2 status?', 'Legacy; removed in Linux-PAM 1.5.0. Use `pam_faillock` with `/etc/security/faillock.conf`; unlock with `faillock --user bob --reset`.'),
  c('3.4', 'pwquality negative credit?', '`dcredit = -1` means at least one digit (likewise `ucredit`, `lcredit`, `ocredit`). Positive values give length credit.'),
  c('3.5', 'LUKS2 default KDF?', 'Argon2id (memory-hard). LUKS1 used PBKDF2. Check with `cryptsetup luksDump`.'),
  c('3.5', 'Deprecated TLS versions?', 'TLS 1.0 and 1.1 (RFC 8996). Use TLS 1.2 with AEAD suites or TLS 1.3.'),
  c('3.5', 'Hash vs HMAC?', 'Hash (SHA-256): integrity if the digest is trusted. HMAC: hash keyed with a shared secret, so integrity plus authenticity.'),
  c('3.6', '`rpm -V` codes?', '`S` size, `M` mode, `5` digest, `L` link, `U` user, `G` group, `T` mtime; `c` = config file. `5` on a binary is a red flag.'),
  c('3.6', '/etc/issue vs /etc/issue.net vs /etc/motd?', 'issue: local console before login. issue.net: network logins (sshd only with `Banner /etc/issue.net`). motd: after login.'),
];
